{
  "root_cause": "The datepicker's calendar popup does not hide when the input loses focus via keyboard navigation (Tab key), because the dismiss logic only responds to focusin on document and pointerdown, which may not fire in time or may be intercepted by the calendar's own keyboard handling. The calendar remains open and intercepts the Tab key, preventing focus movement.",
  "repair_strategy": "Add a blur event listener on the input element to hide the calendar when the input loses focus, ensuring keyboard navigation works naturally.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onBlur: (() => void) | null"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _setupDismiss(): void {
    if (this._isInline) {
      return
    }

    // VCP schedules a show on every click of its trigger, after the data API
    // toggle runs. When that toggle closed the popup, cancel the reopen.
    // `hide()` on VCP clears its pending show even when already hidden.
    if (!this._isInput) {
      this._onTriggerClick = () => {
        if (!this._isShown) {
          this._calendar?.hide()
        }
      }

      EventHandler.on(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    this._onOutside = ({ target }) => {
      const mainElement = this._calendar?.context?.mainElement
      const isOutside = !(target instanceof Node) || (!this._element.contains(target) && !mainElement?.contains(target))

      if (this._isShown && isOutside) {
        this.hide()
      }
    }

    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)
  }",
      "after": "  protected _setupDismiss(): void {
    if (this._isInline) {
      return
    }

    // VCP schedules a show on every click of its trigger, after the data API
    // toggle runs. When that toggle closed the popup, cancel the reopen.
    // `hide()` on VCP clears its pending show even when already hidden.
    if (!this._isInput) {
      this._onTriggerClick = () => {
        if (!this._isShown) {
          this._calendar?.hide()
        }
      }

      EventHandler.on(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._isInput) {
      this._onBlur = () => {
        if (this._isShown) {
          this.hide()
        }
      }
      EventHandler.on(this._element, 'blur' + EVENT_KEY, this._onBlur)
    }

    this._onOutside = ({ target }) => {
      const mainElement = this._calendar?.context?.mainElement
      const isOutside = !(target instanceof Node) || (!this._element.contains(target) && !mainElement?.contains(target))

      if (this._isShown && isOutside) {
        this.hide()
      }
    }

    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onBlur) {
      EventHandler.off(this._element, 'blur' + EVENT_KEY, this._onBlur)
      this._onBlur = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key will move focus from the date field to the passengers field because the calendar will hide when the date field loses focus, allowing natural keyboard navigation.",
  "functional_risks": [
    "Calendar may hide unexpectedly if the input loses focus momentarily during browser focus shifts.",
    "Calendar may not hide if focus moves to the calendar itself (unlikely with inputMode)."
  ],
  "verification_requirements": [
    "Verify that pressing Tab when the date field has focus moves focus to the passengers field.",
    "Verify that clicking the date field still shows the calendar.",
    "Verify that pressing Escape when the calendar is shown hides the calendar and moves focus back to the date field.",
    "Verify that selecting a date from the calendar updates the input value correctly.",
    "Verify that the calendar is positioned near the input field as intended."
  ]
}
